ALTER TABLE public.telegram_delivery_logs ADD COLUMN acknowledged_at timestamptz;
ALTER TABLE public.growth_spins ADD COLUMN telegram_state text NOT NULL DEFAULT 'pending' CHECK(telegram_state IN ('pending','sending','sent','failed','unknown'));
ALTER TABLE public.growth_campaigns ADD COLUMN budget_ton numeric(24,9) NOT NULL DEFAULT 0 CHECK(budget_ton>=0), ADD COLUMN claim_until timestamptz, ADD COLUMN fee_terms text NOT NULL DEFAULT 'No participation fee. Token payouts unavailable until treasury and payout verification are configured.';
CREATE TABLE public.product_referrals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES public.products(id),affiliate_user_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(product_id,affiliate_user_id));
GRANT SELECT ON public.product_referrals TO authenticated; GRANT ALL ON public.product_referrals TO service_role; ALTER TABLE public.product_referrals ENABLE ROW LEVEL SECURITY; CREATE POLICY "own affiliate links" ON public.product_referrals FOR SELECT TO authenticated USING(affiliate_user_id=auth.uid());
CREATE TABLE public.buyer_product_referrals(buyer_id uuid NOT NULL,product_id uuid NOT NULL REFERENCES public.products(id),referral_id uuid NOT NULL REFERENCES public.product_referrals(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(buyer_id,product_id));
GRANT SELECT ON public.buyer_product_referrals TO authenticated; GRANT ALL ON public.buyer_product_referrals TO service_role; ALTER TABLE public.buyer_product_referrals ENABLE ROW LEVEL SECURITY; CREATE POLICY "own attribution" ON public.buyer_product_referrals FOR SELECT TO authenticated USING(buyer_id=auth.uid());
ALTER TABLE public.orders ADD COLUMN product_referral_id uuid REFERENCES public.product_referrals(id);
CREATE FUNCTION public.bind_product_referral(_buyer uuid,_referral uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r product_referrals; owner uuid; BEGIN SELECT * INTO r FROM product_referrals WHERE id=_referral; SELECT s.owner_id INTO owner FROM products p JOIN shops s ON s.id=p.shop_id WHERE p.id=r.product_id AND p.status='active' AND s.status='active'; IF r.id IS NULL OR owner IS NULL OR r.affiliate_user_id IN (_buyer,owner) OR NOT EXISTS(SELECT 1 FROM affiliates WHERE user_id=r.affiliate_user_id AND status='active') THEN RAISE EXCEPTION 'Referral not eligible'; END IF; INSERT INTO buyer_product_referrals(buyer_id,product_id,referral_id) VALUES(_buyer,r.product_id,r.id) ON CONFLICT(buyer_id,product_id) DO NOTHING; RETURN r.product_id; END $$;
REVOKE ALL ON FUNCTION public.bind_product_referral(uuid,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.bind_product_referral(uuid,uuid) TO service_role;
CREATE TABLE public.shop_quizzes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),shop_id uuid NOT NULL REFERENCES public.shops(id),campaign_id uuid NOT NULL REFERENCES public.growth_campaigns(id),title text NOT NULL,question text NOT NULL,options jsonb NOT NULL CHECK(jsonb_array_length(options) BETWEEN 2 AND 4),points integer NOT NULL CHECK(points BETWEEN 1 AND 10000),entries integer NOT NULL DEFAULT 1 CHECK(entries BETWEEN 1 AND 10),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.shop_quizzes TO authenticated; GRANT ALL ON public.shop_quizzes TO service_role; ALTER TABLE public.shop_quizzes ENABLE ROW LEVEL SECURITY; CREATE POLICY "visible quizzes" ON public.shop_quizzes FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM growth_campaigns c WHERE c.id=campaign_id));
CREATE TABLE public.shop_quiz_answers(quiz_id uuid PRIMARY KEY REFERENCES public.shop_quizzes(id),correct_index integer NOT NULL CHECK(correct_index BETWEEN 0 AND 3)); GRANT ALL ON public.shop_quiz_answers TO service_role; ALTER TABLE public.shop_quiz_answers ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.shop_points(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),shop_id uuid NOT NULL REFERENCES public.shops(id),user_id uuid NOT NULL,quiz_id uuid NOT NULL REFERENCES public.shop_quizzes(id),amount integer NOT NULL CHECK(amount>0),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,quiz_id));
GRANT SELECT ON public.shop_points TO authenticated; GRANT ALL ON public.shop_points TO service_role; ALTER TABLE public.shop_points ENABLE ROW LEVEL SECURITY; CREATE POLICY "own shop points" ON public.shop_points FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM shops s WHERE s.id=shop_id AND s.owner_id=auth.uid()));
CREATE FUNCTION public.create_shop_quiz(_actor uuid,_campaign uuid,_title text,_question text,_options jsonb,_correct integer,_points integer,_entries integer) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c growth_campaigns; qid uuid; BEGIN SELECT * INTO c FROM growth_campaigns WHERE id=_campaign; IF c.id IS NULL OR (NOT public.has_role(_actor,'admin') AND NOT EXISTS(SELECT 1 FROM shops WHERE id=c.shop_id AND owner_id=_actor)) THEN RAISE EXCEPTION 'Forbidden'; END IF; IF length(_title) NOT BETWEEN 3 AND 120 OR length(_question) NOT BETWEEN 3 AND 1000 OR _correct<0 OR _correct>=jsonb_array_length(_options) THEN RAISE EXCEPTION 'Invalid quiz'; END IF; INSERT INTO shop_quizzes(shop_id,campaign_id,title,question,options,points,entries) VALUES(c.shop_id,c.id,_title,_question,_options,_points,_entries) RETURNING id INTO qid; INSERT INTO shop_quiz_answers VALUES(qid,_correct); RETURN qid; END $$;
CREATE FUNCTION public.play_shop_quiz(_user uuid,_quiz uuid,_answer integer) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q shop_quizzes; c growth_campaigns; BEGIN SELECT * INTO q FROM shop_quizzes WHERE id=_quiz; SELECT * INTO c FROM growth_campaigns WHERE id=q.campaign_id FOR UPDATE; IF c.id IS NULL OR c.status<>'active' OR now()<c.starts_at OR now()>=c.ends_at THEN RAISE EXCEPTION 'Campaign not open'; END IF; IF NOT EXISTS(SELECT 1 FROM growth_members WHERE campaign_id=c.id AND user_id=_user) THEN RAISE EXCEPTION 'Join campaign first'; END IF; IF EXISTS(SELECT 1 FROM shop_points WHERE quiz_id=_quiz AND user_id=_user) THEN RAISE EXCEPTION 'Already rewarded'; END IF; IF NOT EXISTS(SELECT 1 FROM shop_quiz_answers WHERE quiz_id=_quiz AND correct_index=_answer) THEN RAISE EXCEPTION 'Incorrect answer'; END IF; INSERT INTO shop_points(shop_id,user_id,quiz_id,amount) VALUES(q.shop_id,_user,q.id,q.points); UPDATE growth_members SET entries=least(c.max_entries,entries+q.entries) WHERE campaign_id=c.id AND user_id=_user; INSERT INTO growth_events(campaign_id,actor_id,event) VALUES(c.id,_user,'quiz_reward'); RETURN q.points; END $$;
REVOKE ALL ON FUNCTION public.create_shop_quiz(uuid,uuid,text,text,jsonb,integer,integer,integer),public.play_shop_quiz(uuid,uuid,integer) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.create_shop_quiz(uuid,uuid,text,text,jsonb,integer,integer,integer),public.play_shop_quiz(uuid,uuid,integer) TO service_role;
CREATE FUNCTION public.configure_growth_terms(_actor uuid,_campaign uuid,_budget numeric,_claim timestamptz,_fees text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c growth_campaigns; BEGIN SELECT * INTO c FROM growth_campaigns WHERE id=_campaign FOR UPDATE; IF c.id IS NULL OR (NOT public.has_role(_actor,'admin') AND NOT EXISTS(SELECT 1 FROM shops WHERE id=c.shop_id AND owner_id=_actor)) THEN RAISE EXCEPTION 'Forbidden'; END IF; IF c.status='active' OR EXISTS(SELECT 1 FROM growth_spins WHERE campaign_id=c.id) THEN RAISE EXCEPTION 'Terms locked after launch'; END IF; IF _budget<0 OR _claim<c.ends_at OR length(_fees) NOT BETWEEN 10 AND 1000 THEN RAISE EXCEPTION 'Invalid terms'; END IF; UPDATE growth_campaigns SET budget_ton=_budget,claim_until=_claim,fee_terms=_fees,status='pending' WHERE id=c.id; INSERT INTO growth_events(campaign_id,actor_id,event) VALUES(c.id,_actor,'terms_updated'); END $$;
REVOKE ALL ON FUNCTION public.configure_growth_terms(uuid,uuid,numeric,timestamptz,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.configure_growth_terms(uuid,uuid,numeric,timestamptz,text) TO service_role;